import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        R = int(next(iterator))
        C = int(next(iterator))
    except StopIteration:
        return

    matrix = []
    for _ in range(R):
        row = []
        for _ in range(C):
            row.append(int(next(iterator)))
        matrix.append(row)

    if C == 0:
        print(-1)
        return

    unsafe = [[False] * C for _ in range(R)]

    for r in range(R):
        for c in range(C):
            if matrix[r][c] == 0:
                unsafe[r][c] = True
                if r > 0:
                    unsafe[r-1][c] = True
                if r < R - 1:
                    unsafe[r+1][c] = True
                if c > 0:
                    unsafe[r][c-1] = True
                if c < C - 1:
                    unsafe[r][c+1] = True

    dist = [[-1] * C for _ in range(R)]
    queue = deque()

    for r in range(R):
        if not unsafe[r][0]:
            dist[r][0] = 1
            queue.append((r, 0))

    if not queue:
        print(-1)
        return

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    min_dist = float('inf')

    while queue:
        r, c = queue.popleft()

        if c == C - 1:
            if dist[r][c] < min_dist:
                min_dist = dist[r][c]
            continue

        d = dist[r][c]
        if d >= min_dist:
            continue

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C:
                if not unsafe[nr][nc] and dist[nr][nc] == -1:
                    dist[nr][nc] = d + 1
                    queue.append((nr, nc))

    if min_dist == float('inf'):
        print(-1)
    else:
        print(min_dist)

if __name__ == "__main__":
    solve()
